import Carteira from "../../components/card";
import Arron, { ArrowLeftSquare, ArrowRightSquare } from 'react-bootstrap-icons';
import { DivCenter } from "../../helpers/StylesDiv";

function Home () {
    return (
    <>
        <Carteira/>
        <DivCenter>
            <ArrowLeftSquare className="arrow"/><ArrowRightSquare/>
        </DivCenter>  
    </>
    );
}

export default Home;
